class Solution {
    /**
    In this Kata, you have to sort an array of non-negative integers according to
    number of ones in their binary representation in ascending order.
    For similar number of ones, sort based on decimal value.
    <p>
    It must be implemented like this:
    >>> sortArrayByBin(Arrays.asList(1, 5, 2, 3, 4)).equals(Arrays.asList(1, 2, 3, 4, 5))
    >>> sortArrayByBin(Arrays.asList(-2, -3, -4, -5, -6)).equals(Arrays.asList(-6, -5, -4, -3, -2))
    >>> sortArrayByBin(Arrays.asList(1, 0, 2, 3, 4)).equals(Arrays.asList(0, 1, 2, 3, 4))
     */
    public List<Integer> sortArrayByBin(List<Integer> arr) {
        arr.sort((a, b) -> {
            int onesA = Integer.bitCount(a);
            int onesB = Integer.bitCount(b);
            if (onesA != onesB) {
                return Integer.compare(onesA, onesB);
            } else {
                return Integer.compare(a, b);
            }
        });
        return arr;
    }
}

