class Solution {
    /**
    You are given an array arr of integers and you need to return
    sum of magnitudes of integers multiplied by product of all signs
    of each number in the array, represented by 1, -1 or 0.
    Note: return None for empty arr.

    Example:
    >>> prodSigns(Arrays.asList(1, 2, 2, -4)) == -9
    >>> prodSigns(Arrays.asList(0, 1)) == 0
    >>> prodSigns(Arrays.asList()) == None
     */
    public Optional<Integer> prodSigns(List<Integer> arr) {
        if (arr.isEmpty()) {
            return Optional.empty();
        }

        int sumOfMagnitudes = 0;
        int productOfSigns = 1;

        for (int num : arr) {
            sumOfMagnitudes += Math.abs(num);
            if (num == 0) {
                productOfSigns = 0;
                break;
            } else if (num < 0) {
                productOfSigns *= -1;
            }
        }

        return Optional.of(sumOfMagnitudes * productOfSigns);
    }
}

import java.util.*;

class Solution {
    /**
    Given a grid with N rows and N columns (N >= 2) and a positive integer k,
    each cell of the grid contains a value. Every integer in the range [1, N * N]
    inclusive appears exactly once on the cells of the grid.

    You have to find the minimum path of length k in the grid. You can start
    from any cell, and in each step you can move to any of the neighbor cells,
    in other words, you can go to cells which share an edge with you current
    cell.
    Please note that a path of length k means visiting exactly k cells (not
    necessarily distinct).
    You CANNOT go off the grid.
    A path A (of length k) is considered less than a path B (of length k) if
    after making the ordered lists of the values on the cells that A and B go
    through (let's call them lst_A and lst_B), lst_A is lexicographically less
    than lst_B, in other words, there exist an integer index i (1 <= i <= k)
    such that lst_A[i] < lst_B[i] and for any j (1 <= j < i) we have
    lst_A[j] = lst_B[j].
    It is guaranteed that the answer is unique.
    Return an ordered list of the values on the cells that the minimum path go through.

    Examples:

        Input: grid = [ [1,2,3], [4,5,6], [7,8,9]], k = 3
        Output: [1, 2, 1]

        Input: grid = [ [5,9,3], [4,1,6], [7,8,2]], k = 1
        Output: [1]
     */
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        List<Integer> result = new ArrayList<>(Collections.nCopies(k, Integer.MAX_VALUE));

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dfs(grid, i, j, k, new ArrayList<>(), result);
            }
        }

        return result;
    }

    private void dfs(List<List<Integer>> grid, int x, int y, int k, List<Integer> path, List<Integer> result) {
        if (path.size() == k) {
            if (isLexicographicallySmaller(path, result)) {
                for (int i = 0; i < k; i++) {
                    result.set(i, path.get(i));
                }
            }
            return;
        }

        int n = grid.size();
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        path.add(grid.get(x).get(y));

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];

            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                dfs(grid, nx, ny, k, path, result);
            }
        }

        path.remove(path.size() - 1);
    }

    private boolean isLexicographicallySmaller(List<Integer> path, List<Integer> result) {
        for (int i = 0; i < path.size(); i++) {
            if (path.get(i) < result.get(i)) {
                return true;
            } else if (path.get(i) > result.get(i)) {
                return false;
            }
        }
        return false;
    }
}

import java.util.*;
