class Solution {
    /**
    Create a function that takes a string as input which contains only square brackets.
    The function should return true if and only if there is a valid subsequence of brackets
    where at least one bracket in the subsequence is nested.

    isNested("[[]]") -> true
    isNested("[]]]]]]][[[[[]") -> false
    isNested("[][]") -> false
    isNested("[]") -> false
    isNested("[[][]]") -> true
    isNested("[[]][[") -> true
     */
    public boolean isNested(String string) {
        int depth = 0;
        boolean hasNested = false;

        for (char ch : string.toCharArray()) {
            if (ch == '[') {
                depth++;
                if (depth > 1) {
                    hasNested = true;
                }
            } else if (ch == ']') {
                if (depth > 0) {
                    depth--;
                } else {
                    // Unmatched closing bracket, invalid sequence
                    return false;
                }
            }
        }

        // If depth is not zero here, it means there are unmatched opening brackets
        return hasNested && depth == 0;
    }
}

