class Solution {
    /**
    You are given a positive integer n. You have to create an integer array a of length n.
        For each i (1 <= i <= n), the value of a[i] = i * i - i + 1.
        Return the number of triples (a[i], a[j], a[k]) of a where i < j < k,
    and a[i] + a[j] + a[k] is a multiple of 3.

    Example :
        Input: n = 5
        Output: 1
        Explanation:
        a = [1, 3, 7, 13, 21]
        The only valid triple is (1, 7, 13).
     */
    public int getMaxTriples(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = (i + 1) * (i + 1) - (i + 1) + 1;
        }

        int count0 = 0, count1 = 0, count2 = 0;
        for (int num : a) {
            if (num % 3 == 0) {
                count0++;
            } else if (num % 3 == 1) {
                count1++;
            } else {
                count2++;
            }
        }

        int result = 0;
        // All elements with remainder 0
        result += count0 * (count0 - 1) * (count0 - 2) / 6;
        // All elements with remainder 1
        result += count1 * (count1 - 1) * (count1 - 2) / 6;
        // All elements with remainder 2
        result += count2 * (count2 - 1) * (count2 - 2) / 6;
        // One element from each remainder group
        result += count0 * count1 * count2;

        return result;
    }
}

