class Solution {
    /**
    Given two lists operator, and operand. The first list has basic algebra operations, and
    the second list is a list of integers. Use the two given lists to build the algebric
    expression and return the evaluation of this expression.

    The basic algebra operations:
    Addition ( + )
    Subtraction ( - )
    Multiplication ( * )
    Floor division ( / )
    Exponentiation ( ** )

    Example:
    operator["+", "*", "-"]
    array = [2, 3, 4, 5]
    result = 2 + 3 * 4 - 5
    => result = 9

    Note:
        The length of operator list is equal to the length of operand list minus one.
        Operand is a list of of non-negative integers.
        Operator list has at least one operator, and operand list has at least two operands.
     */
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        if (operator.size() != operand.size() - 1) {
            throw new IllegalArgumentException("The length of operator list must be one less than the length of operand list.");
        }

        // Start with the first operand
        int result = operand.get(0);

        // Iterate through operators and operands
        for (int i = 0; i < operator.size(); i++) {
            String op = operator.get(i);
            int nextOperand = operand.get(i + 1);

            switch (op) {
                case "+":
                    result += nextOperand;
                    break;
                case "-":
                    result -= nextOperand;
                    break;
                case "*":
                    result *= nextOperand;
                    break;
                case "/":
                    if (nextOperand == 0) {
                        throw new ArithmeticException("Division by zero");
                    }
                    result /= nextOperand;
                    break;
                case "**":
                    result = (int) Math.pow(result, nextOperand);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid operator: " + op);
            }
        }

        return result;
    }
}

        boolean hasLetters = false;
        StringBuilder result = new StringBuilder();

        for (char c : s.toCharArray()) {
            if (Character.isLetter(c)) {
                hasLetters = true;
                if (Character.isUpperCase(c)) {
                    result.append(Character.toLowerCase(c));
                } else {
                    result.append(Character.toUpperCase(c));
                }
            } else {
                result.append(c);
            }
        }

        return hasLetters ? result.toString() : result.reverse().toString();
    }
}

        if (text.isEmpty()) {
            return Optional.empty();
        }
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(text.getBytes());
        BigInteger number = new BigInteger(1, hashBytes);
        String hashtext = number.toString(16);
        // Add leading zeros to make it 32 characters long
        while (hashtext.length() < 32) {
            hashtext = "0" + hashtext;
        }
        return Optional.of(hashtext);
    }
}

import java.util.*;
import java.lang.*;

class Solution {
    /**
    Given two positive integers a and b, return the even digits between a
    and b, in ascending order.

    For example:
    generateIntegers(2, 8) => [2, 4, 6, 8]
    generateIntegers(8, 2) => [2, 4, 6, 8]
    generateIntegers(10, 14) => []
     */
    public List<Integer> generateIntegers(int a, int b) {
        List<Integer> result = new ArrayList<>();
        int start = Math.min(a, b);
        int end = Math.max(a, b);

        for (int i = start; i <= end; i++) {
            if (i % 2 == 0) {
                result.add(i);
            }
        }

        return result;
    }
}
